import React from 'react'
import moment from 'moment-timezone'
import { Button, Icon } from 'antd'
import { FilterInput } from '../../../../../components/tables/helperCells'

export function getAgentColumns (userTimeZone) {
  return [
    {
      key: 'name',
      title: 'Mitra Name',
      dataIndex: 'name',
      align: 'center'
    },
    {
      key: 'agent_code',
      title: 'Mitra Code',
      dataIndex: 'agent_code',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: this.state.searchTextQuery.code && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='agent_code_id'
          className='agent-table-search'
          searchText={this.state.isChange ? this.state.searchTextQuery.code : this.state.code}
          onInputChange={e => this.handleInputChange(e, 'code')}
          onSearch={e => this.handleSearch(e, 'code')}
        />
      ),
      filterDropdownVisible: this.state.isFilterVisible === 'code',
      onFilterDropdownVisibleChange: (visible) => this.setState({ isFilterVisible: visible ? 'code' : '' })
    },
    {
      key: 'email',
      title: 'Email',
      dataIndex: 'email',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: this.state.searchTextQuery.email && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='email_id'
          className='agent-table-search'
          searchText={this.state.isChange ? this.state.searchTextQuery.email : this.state.email}
          onInputChange={e => this.handleInputChange(e, 'email')}
          onSearch={e => this.handleSearch(e, 'email')}
        />
      ),
      filterDropdownVisible: this.state.isFilterVisible === 'email',
      onFilterDropdownVisibleChange: (visible) => this.setState({ isFilterVisible: visible ? 'email' : '' })
    },
    {
      key: 'phone_no',
      title: 'Phone Number',
      dataIndex: 'phone_no',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: this.state.searchTextQuery.phone && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='phone_no_id'
          className='agent-table-search'
          searchText={this.state.isChange ? this.state.searchTextQuery.phone : this.state.phone}
          onInputChange={e => this.handleInputChange(e, 'phone')}
          onSearch={e => this.handleSearch(e, 'phone')}
        />
      ),
      filterDropdownVisible: this.state.isFilterVisible === 'phone',
      onFilterDropdownVisibleChange: visible => this.setState({ isFilterVisible: visible ? 'phone' : '' })
    },
    {
      key: 'ktp_no',
      title: 'KTP',
      dataIndex: 'ktp_no',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: this.state.searchTextQuery.ktp_no && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='ktp_no_id'
          className='agent-table-search'
          searchText={this.state.isChange ? this.state.searchTextQuery.ktp_no : this.state.ktp_no}
          onInputChange={e => this.handleInputChange(e, 'ktp_no')}
          onSearch={e => this.handleSearch(e, 'ktp_no')}
        />
      ),
      filterDropdownVisible: this.state.isFilterVisible === 'ktp_no',
      onFilterDropdownVisibleChange: visible => this.setState({ isFilterVisible: visible ? 'ktp_no' : '' })
    },
    {
      key: 'npwp_no',
      title: 'NPWP',
      dataIndex: 'npwp_no',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: this.state.searchTextQuery.npwp_no && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='npwp_no_id'
          className='agent-table-search'
          searchText={this.state.isChange ? this.state.searchTextQuery.npwp_no : this.state.npwp_no}
          onInputChange={e => this.handleInputChange(e, 'npwp_no')}
          onSearch={e => this.handleSearch(e, 'npwp_no')}
        />
      ),
      filterDropdownVisible: this.state.isFilterVisible === 'npwp_no',
      onFilterDropdownVisibleChange: visible => this.setState({ isFilterVisible: visible ? 'npwp_no' : '' })
    },
    {
      key: 'submitted_date',
      title: 'Submitted Date',
      dataIndex: 'submit_approval_request_date',
      render: date => moment(date).tz(userTimeZone).format('YYYY-MM-DD'),
      align: 'center'
    },
    {
      key: 'name',
      title: 'Action',
      render: (text, record) => (
        <Button
          type='primary'
          className='agent-verify-btn'
          onClick={e => this.handleVerifyData(record)}
        >
          Verify Data
        </Button>
      )
    }
  ]
}

export const VERIFY_MODAL_DATA = [
  {
    name: 'Agent name',
    key: 'name'
  },
  {
    name: 'KTP',
    key: 'ktp_no'
  },
  {
    name: 'NPWP',
    key: 'npwp_no'
  }
]

export const KTP_NPWP_ACTIONS = [
  {
    label: 'Reject',
    value: false
  },
  {
    label: 'Accept',
    value: true
  }
]
