import { Select } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { showNotification } from '../../../../../components/ShowNotification'
import agentAction from '../../../../redux/agent/actions'

const { updateAgentOrgType, resetAgentRedux } = agentAction

function AgentOrgType (props) {
  const { data = {}, defaultValue } = props
  const [selectedType, setSelectType] = useState(data.agent_type || 'REGULAR AGENT')

  const handleTypeSelection = useCallback((value) => {
    const { profile, data } = props
    if (data.agent_type === 'CORPORATE AGENT') return
    setSelectType(value)
    props.updateAgentOrgType({
      body: {
        changed_by: profile.email,
        agent_type: value
      },
      agentId: data.agent_ref
    })
  }, [props])

  const checkTagType = () => {
    let check = false
    if (data.agent_tags) {
      data.agent_tags.forEach(item => {
        if (item.tag_type === 'staff') {
          check = true
        }
      })
    }
    return check
  }

  useEffect(() => {
    const { updateAgentOrgTypeStatus, updateAgentOrgTypeData, resetAgentRedux, onSuccess } = props
    if (updateAgentOrgTypeStatus === 'success') {
      showNotification('success', updateAgentOrgTypeData.message)
      if (onSuccess) {
        onSuccess()
      }
      resetAgentRedux(['updateAgentOrgTypeStatus'])
    } else if (updateAgentOrgTypeStatus) {
      showNotification('error', updateAgentOrgTypeStatus)
      resetAgentRedux(['updateAgentOrgTypeStatus'])
    }
  }, [props])

  return (
    <Select
      placeholder='Pilih ...'
      defaultValue={defaultValue || 'REGULAR AGENT'}
      className='agent-header-dropdown'
      value={selectedType}
      disabled={(checkTagType() || data.agent_type === 'CORPORATE AGENT')}
      onChange={handleTypeSelection}
    >
      <Select.Option value='REGULAR AGENT'>Normal Individual Agents</Select.Option>
      <Select.Option value='CORPORATE AGENT'>Corporate Agents</Select.Option>
    </Select>
  )
}

export default connect(
  (state) => ({
    profile: state.Auth.profile,
    updateAgentOrgTypeData: state.Agent.updateAgentOrgTypeData,
    updateAgentOrgTypeStatus: state.Agent.updateAgentOrgTypeStatus
  }),
  {
    resetAgentRedux,
    updateAgentOrgType
  }
)(AgentOrgType)
