import React, { useEffect, useState } from 'react'
import KTPandNPWPDetail from '../AgentVerification/components/KTPandNPWPDetail'
import AgentLayoutWrapper from '../agent.style'
import { connect } from 'react-redux'
import { Button, Modal, Row } from 'antd'
import { AgentVerifcationZohoStyle } from './index.style'
import RejectAgent from './components/RejectAgent'
import { get, isEmpty } from 'lodash'
import { showNotification } from '../../../../components/ShowNotification'
import CircularLoader from '../../../../components/CircularLoader'
import agentRedux from 'agentOps/agentRedux'

const { getAgentVerificationDetail, resetAgentVerificationRedux: resetAgentRedux } = agentRedux?.agentReduxActions

function AgentVerifcationZoho (props) {
  const { agentRef } = props.match.params
  const {
    getAgentVerificationDetail, agentVerificationDetail = {},
    submitVerificationMsg, resetAgentRedux, submitLoading
  } = props

  const [isShowModal, setIsShowModal] = useState(false)

  const handleCloseModal = () => {
    setIsShowModal(false)
  }

  const handleRejectAgent = () => {
    setIsShowModal(true)
  }

  useEffect(() => {
    if (submitVerificationMsg === 'success') {
      getAgentVerificationDetail({ agentRef })
    } else if (submitVerificationMsg) {
      showNotification('error', submitVerificationMsg)
    }
    if (isEmpty(agentVerificationDetail)) {
      getAgentVerificationDetail({ agentRef })
    }
    return () => {
      resetAgentRedux(['submitVerificationMsg'])
    }
  }, [agentRef, getAgentVerificationDetail, submitVerificationMsg, resetAgentRedux])

  return (
    <AgentVerifcationZohoStyle>
      <CircularLoader isSpining={submitLoading}>
        {
          !isEmpty(agentVerificationDetail) &&
            <AgentLayoutWrapper>
              <Row className='w-100' type='flex' align='space-between'>
                <h2> Agent Details </h2>
                {
                get(agentVerificationDetail, 'is_active', false) &&
                  <Button onClick={handleRejectAgent}> Reject Agent </Button>
              }
              </Row>
              <Modal
                title='Reject Agent'
                visible={isShowModal}
                onCancel={handleCloseModal}
                footer={false}
                className='agent-verification-modal'
                width={600}
              >
                <RejectAgent closeModal={handleCloseModal} agentRef={agentRef} />
              </Modal>
              <Row className='w-100'>
                <KTPandNPWPDetail
                  data={{
                    ...(agentVerificationDetail || {}),
                    agent_ref: agentRef
                  }}
                  scenario='zoho'
                />
              </Row>
            </AgentLayoutWrapper>

        }
      </CircularLoader>
    </AgentVerifcationZohoStyle>
  )
}

export default connect(
  state => ({
    submitLoading: state.Loading.SUBMIT_AGENT_VERIFICATION,
    agentVerificationDetail: state.AgentVerification.agentVerificationDetail,
    agentVerificationDetailMsg: state.AgentVerification.agentVerificationDetailMsg,
    submitVerificationMsg: state.AgentVerification.submitVerificationMsg
  }),
  {
    getAgentVerificationDetail,
    resetAgentRedux
  }
)(AgentVerifcationZoho)
