import React, { Component } from 'react'
import { connect } from 'react-redux'
import agentActions from '../../../../redux/agent/actions'
import GenericQuestion from './GenericQuestion'

const { getAgentQuestionnaireDetails } = agentActions

class Questionnaire extends Component {
  componentDidMount () {
    this.props.getAgentQuestionnaireDetails(this.props.agentRef)
  }

  componentDidUpdate (prevProps) {
    if (prevProps.agentRef && (prevProps.agentRef !== this.props.agentRef)) {
      this.props.getAgentQuestionnaireDetails(this.props.agentRef)
    }
  }

  render () {
    const { questionsData = {} } = this.props
    return (
      <>
        {
          questionsData.questions && (!!questionsData.questions.length) && (
            <GenericQuestion questions={questionsData.questions} />
          )
        }
      </>
    )
  }
}

export default connect(
  state => ({
    questionsData: state.Agent.agentQuestionnaireDetail,
    questionsStatus: state.Agent.agentQuestionnaireStatus
  }),
  {
    getAgentQuestionnaireDetails
  }
)(Questionnaire)
