import { useEffect, useRef } from 'react'
import { PreventCopyStyle } from './index.style'

function PreventCopy ({ children }) {
  const refElm = useRef()

  useEffect(() => {
    function handlerPreventCopy (e) {
      e.preventDefault()
      return false
    }
    const copyEvent = refElm.current
    copyEvent && copyEvent.addEventListener('copy', handlerPreventCopy)
    return () => {
      copyEvent && copyEvent.removeEventListener('copy', handlerPreventCopy)
    }
  }, [])

  return (
    <PreventCopyStyle ref={refElm}>
      {children}
    </PreventCopyStyle>
  )
}

export default PreventCopy
