import React, { Component } from 'react'
import {
  Button,
  Select,
  Form,
  Input,
  Row
} from 'antd'
import agentAction from '../../../../../redux/agent/actions'
import { connect } from 'react-redux'
import agentRedux from 'agentOps/agentRedux'
import { showNotification } from '../../../../../../components/ShowNotification'

const Option = Select.Option
const { rejectAgent, resetAgentRedux } = agentAction
const { getAgentVerificationDetail } = agentRedux?.agentReduxActions

class RejectAgent extends Component {
  constructor (props) {
    super(props)
    this.state = {
      remark: ''
    }
    this.selectOptions = [
      'Health insurance agent',
      'Student',
      'Housewife',
      'Employee',
      'Unemployment',
      'Trader',
      'Farmer',
      'Entrepreneur',
      'Social Worker',
      'Car Sales',
      'Property Sales',
      'Others'
    ]
  }

  componentDidUpdate (props) {
    const { rejectAgentMsg, getAgentVerificationDetail, agentRef, closeModal } = this.props
    if (props.rejectAgentMsg !== rejectAgentMsg) {
      if (rejectAgentMsg === 'success') {
        closeModal()
        getAgentVerificationDetail({ agentRef })
      } else {
        showNotification('error', rejectAgentMsg)
      }
    }
  }

  handleRejectReasonChange = (value) => {
    this.props.form.setFieldsValue({
      remark: value
    })
  }

  componentWillUnmount () {
    const { resetAgentRedux } = this.props
    resetAgentRedux(['rejectAgentMsg'])
  }

  handleRejectAgent = (e) => {
    e.preventDefault()
    const { agentRef } = this.props
    this.props.form.validateFields((err, values) => {
      if (!err) {
        let remark = values.remark
        if (remark === 'Others') {
          remark = values.remarkText
        }
        this.props.rejectAgent({ rejectedReason: remark, agentRef: agentRef })
      }
    })
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const { closeModal } = this.props
    return (
      <Form name='basic' onSubmit={this.handleRejectAgent}>
        <Form.Item
          label='Reason of Agent Rejected'
          name='remark'
        >{
            getFieldDecorator('remark', {
              rules: [{ required: true, message: 'Remark cannot be blank' }]
            })(
              <Select
                placeholder='Reason to Reject Agent'
                onChange={this.handleRejectReasonChange}
              >
                {
                  this.selectOptions.map((op, i) => (
                    <Option key={i} value={op}> {op} </Option>
                  ))
                }
              </Select>
            )
          }
        </Form.Item>
        {
          this.props.form.getFieldValue('remark') === 'Others' &&
            <Form.Item name='remarkText'>
              {
                getFieldDecorator('remarkText', {
                  rules: [{ required: true, message: 'Remark cannot be blank' }]
                })(<Input.TextArea />)
              }
            </Form.Item>
        }
        <p>
          The agent status will change to rejected and an email notification containing the reasons you entered will be sent to the agent once you submit this form.
        </p>
        <Form.Item>
          <Row type='flex' justify='center'>
            <Button style={{ marginRight: 8 }} onClick={closeModal}>
              Cancel
            </Button>
            <Button type='primary' htmlType='submit'>
              Submit
            </Button>
          </Row>
        </Form.Item>
      </Form>
    )
  }
}

const wrapperRejectAgent = Form.create()(RejectAgent)
export default connect(state => ({
  rejectAgentMsg: state.Agent.rejectAgentMsg
}), {
  getAgentVerificationDetail,
  rejectAgent,
  resetAgentRedux
})(wrapperRejectAgent)
