import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { GenericQuestionStyle } from './index.style'
import ProductQuestion from '../ProductQuestion'
import { find } from 'lodash'

class GenericQuestion extends Component {
  static propTypes = {
    questions: PropTypes.array
  }

  renderQuestion = (question = {}) => {
    // handle question rendering here
    if (question.answer && question.answer.value) {
      return (
        <div className='question-box'>
          <div className='question-title'>{question.question}</div>
          <div className='question-answer'>{question.answer.value}</div>
        </div>
      )
    }

    return null
  }

  render () {
    const { questions = [] } = this.props
    const soldProduct = find(questions, { id: 4 }) || {}
    return (
      <>
        <GenericQuestionStyle>
          <div className='title'>Profile</div>
          {
            questions.map((question) => {
              return (this.renderQuestion(question))
            })
          }
        </GenericQuestionStyle>
        {
          soldProduct.answer && soldProduct.answer.value === 'Ya' && (
            <ProductQuestion questionData={soldProduct} />
          )
        }
      </>
    )
  }
}

export default GenericQuestion
