import { find } from 'lodash'
import React, { Component } from 'react'
import TableWrapper from '../../../pagination.style'
import { ProductQuestionStyle } from './index.style'

class ProductQuestion extends Component {
  constructor (props) {
    super(props)
    const { questionData = {} } = this.props
    const questionOptions = questionData.question_option.options
    this.selectedQuestion = find(questionOptions, { title: 'Ya' }) || {}
    // we are reading the first question as of now because we have only one question
    this.selectedQuestion = this.selectedQuestion.questions[0]
  }

  getTableData = () => {
    const { answer, question_option: questionOptions = {} } = this.selectedQuestion
    const options = questionOptions.options || []
    const checkedValue = (answer && answer.checked_value) || {}
    const answerMap = []
    for (let item of options) {
      // handle the key to show the data
      const { questions } = item
      if (checkedValue[item.title] && questions && questions.length) {
        const questionMap = questions[0]
        answerMap.push({
          id: questionMap.id,
          scale: questionMap.answer && questionMap.answer.value,
          title: item.title
        })
      }
    }
    return answerMap
  }

  getTargetColData = () => {
    return [
      {
        key: 'sr_no',
        title: 'Sr No.',
        dataIndex: 'index',
        render: (value, props, index) => {
          return (index + 1)
        },
        width: 100,
        align: 'center'
      },
      {
        key: 'product_name',
        title: 'Insurance Product Name',
        dataIndex: 'title',
        align: 'center'
      },
      {
        key: 'question_scale',
        title: 'Rate',
        dataIndex: 'scale',
        align: 'center'
      }
    ]
  }

  render () {
    return (
      <ProductQuestionStyle>
        <div className='title'>Insurance Product Sold by Agent</div>
        <TableWrapper
          columns={this.getTargetColData()}
          bordered
          rowKey={record => `target_${record.id}`}
          dataSource={this.getTableData()}
          className='isoSearchableTable agent-table-data'
        />
      </ProductQuestionStyle>
    )
  }
}

export default ProductQuestion
