import React, { Component } from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { isEmpty } from 'lodash/lang'
import { get as lodashGet, has } from 'lodash/object'
import { find as lodashFind } from 'lodash/collection'
import { Row, Col, Radio, Input, Button, Select, Form, Table } from 'antd'
import { KTPNPWPStyle } from './index.style'
import './index.css'
import { VERIFY_MODAL_DATA, KTP_NPWP_ACTIONS } from '../../constants'
import { showNotification } from '../../../../../../components/ShowNotification'
import moment from 'moment'
import Questionnaire from '../../../components/Questionnaire'
import CircularLoader from '../../../../../../components/CircularLoader'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import AgentOrgType from '../../../components/AgentOrgType'
import PreventCopy from '../../../components/PreventCopy'
import agentRedux from 'agentOps/agentRedux'

const Option = Select.Option
const { submitAgentVerification } = agentRedux?.agentReduxActions
class KTPandNPWPModal extends Component {
  state = {
    KTP: {}, // this object contains reject/accept and reason for reject
    NPWP: {} // this object contains reject/accept and reason for reject
  }

  static propTypes = {
    data: PropTypes.object
  }

  handleChangeRadio = (e, type) => {
    this.updateStateKeys(type, 'accept', e.target.value)
  }

  rejectDocReasonChange = (type, value) => {
    this.updateStateKeys(type, 'rejectReason', value)
  }

  updateStateKeys = (type, key, value) => {
    this.setState({
      [type]: {
        ...this.state[type],
        [key]: value
      }
    })
  }

  handleTextAreaChange = (e, type) => {
    this.updateStateKeys(type, 'rejectReason', e.target.value)
  }

  checkValidityForField = (data) => {
    let valid = false
    if (data.accept) {
      valid = true
    } else if (!data.accept && (data.rejectReason && data.rejectReason.length >= 10)) {
      valid = true
    }
    return valid
  }

  handleSubmitVerification = () => {
    const { data } = this.props
    const { document: ktpNpwpDocs = [] } = data
    // if i have both documents then user
    // must accept both otherwise NPWP is optional if only
    // KTP submitted by the Mitra/Agent
    const ktpDoc = lodashFind(ktpNpwpDocs, { document_type: 'KTP' })
    const npwpDoc = lodashFind(ktpNpwpDocs, { document_type: 'NPWP' })
    const isKtpSubmitted = lodashGet(ktpDoc, 'status', '') === 'SUBMITTED'
    const isNpwpSubmitted = lodashGet(npwpDoc, 'status', '') === 'SUBMITTED'
    const { KTP, NPWP } = this.state
    if (isEmpty(KTP) && isEmpty(NPWP)) {
      showNotification('error', 'Please provide your input for KTP/NPWP')
      // show error to user and notify user for this
      return false
    }
    if (!isEmpty(KTP) && !has(KTP, 'accept')) {
      showNotification('error', 'Please provide your input for KTP')
      // show error to user and notify user for this
      return false
    }

    if (!isEmpty(NPWP) && !has(NPWP, 'accept')) {
      showNotification('error', 'Please provide your input for NPWP')
      // show error to user and notify user for this
      return false
    }

    if (lodashGet(ktpDoc, 'id', false) && isKtpSubmitted && !this.checkValidityForField(KTP)) {
      showNotification('error', 'Please provide reject reason with a minimum of 10 characters for KTP')
      this.updateStateKeys('KTP', 'error', true)
      return false
    } else if (KTP.error && isKtpSubmitted) {
      this.updateStateKeys('KTP', 'error', false)
    }

    if (lodashGet(npwpDoc, 'id', false) && isNpwpSubmitted && !this.checkValidityForField(NPWP)) {
      showNotification('error', 'Please provide reject reason with a minimum of 10 characters for NPWP')
      this.updateStateKeys('NPWP', 'error', true)
      return false
    } else if (NPWP.error && isNpwpSubmitted) {
      this.updateStateKeys('NPWP', 'error', false)
    }

    const processDocument = []

    if (lodashGet(ktpDoc, 'id', false) && isKtpSubmitted) {
      processDocument.push({
        document_uuid: lodashGet(ktpDoc, 'id', false),
        accept: this.state.KTP.accept,
        reject_reason: !this.state.KTP.accept ? this.state.KTP.rejectReason : ''
      })
    }

    if (lodashGet(npwpDoc, 'id', false) && isNpwpSubmitted) {
      processDocument.push({
        document_uuid: lodashGet(npwpDoc, 'id', false),
        accept: this.state.NPWP.accept,
        reject_reason: !this.state.NPWP.accept ? this.state.NPWP.rejectReason : ''
      })
    }

    // all things provide then submit the form and update the verification list
    this.props.submitAgentVerification({
      user_id: data.email,
      agentId: data.id,
      process_document: processDocument
    })
  }

  getFooterNode = () => {
    const { data } = this.props
    const { document: ktpNpwpDocs = [] } = data
    let showFooter = false

    ktpNpwpDocs.forEach(item => {
      if (item.status === 'SUBMITTED') {
        showFooter = true
      }
    })
    if (showFooter) {
      return (
        <Row type='flex' justify='space-between' align='center'>
          <Col className='verify-submit-notify'>
            Note: When you click submit, it will send notification to agent
          </Col>
          <Col>
            <Button
              type='primary'
              className='btn-margin'
              onClick={this.handleSubmitVerification}
              loading={this.props.submitLoading}
            >
              Submit
            </Button>
          </Col>
        </Row>
      )
    }
  }

  getKeyValueTemplate = (key, value) => {
    return (
      <Row type='flex' key={key} className='verify-agent-row'>
        <Col sm={5} xl={5} className='verify-agent-name'>
          {key}:
        </Col>
        <Col sm={8} xl={8} className='verify-agent-value'>
          {value}
        </Col>
      </Row>
    )
  }

  getImgAndReasonTemplate = (item) => {
    const { id, url, document_type: type } = item
    const { scenario = 'basic' } = this.props
    const { getFieldDecorator } = this.props.form

    let isVerified = lodashGet(item, 'verified', false)
    if (!isVerified && lodashGet(item, 'status', '') === 'REJECTED') {
      isVerified = true
    }

    const selectOptions = [
      'The picture is not clear',
      'Not the original/copy of the document',
      'Not Identity Card/Taxpayer Identification Number Card',
      'The number does not match'
    ]
    return (
      <Row type='flex' key={id} className='agent-reason-section'>
        {
          (scenario === 'basic') && <Col xl={23} sm={23} className='agent-img-name'>{type}</Col>
        }
        {
          (scenario === 'basic') && (
            <Col xl={12} sm={12} className='ktp-npwp-img-box'>
              <img src={url} alt={id} className='ktp-npwp-img' />
            </Col>
          )
        }
        {
          !isVerified && (
            <Col xl={12} sm={10} className='ktp-actions'>
              <Radio.Group
                options={KTP_NPWP_ACTIONS}
                onChange={e => this.handleChangeRadio(e, type)}
              />
              {
                (this.state[type].accept === false) && (scenario === 'zoho'
                  ? (
                    <Form name='basic'>
                      <Form.Item name={`rejectDoc${type}`}>
                        {
                          getFieldDecorator(`rejectDoc${type}`, {
                            rules: [{ required: true, message: 'Reason cannot be blank' }]
                          })(
                            <Select
                              placeholder='Reason to Reject Document'
                              onChange={(val) => this.rejectDocReasonChange(type, val)}
                            >
                              {
                                selectOptions.map((op, i) => (
                                  <Option key={i} value={op}> {op} </Option>
                                ))
                              }
                            </Select>
                          )
                        }
                      </Form.Item>
                    </Form>
                    )
                  : (
                    <Input.TextArea
                      placeholder='Type here the reason'
                      onChange={e => this.handleTextAreaChange(e, type)}
                      className={`agent-reject-text ${this.state[type].error && 'reject-error'}`}
                    />
                    )
                )
              }
            </Col>
          )
        }
      </Row>
    )
  }

  renderTables = (cols) => {
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value',
        render: (val) => {
          return val
        }
      }
    ]
    return (
      <div className='margin-10'>
        <Table
          pagination={false}
          showHeader={false}
          rowKey={data => data.id}
          columns={columns}
          dataSource={cols}
        />
      </div>
    )
  }

  renderZohoData = () => {
    const { data } = this.props
    const { document: ktpNpwpDocs = [] } = data
    const ktpDoc = lodashFind(ktpNpwpDocs, { document_type: 'KTP' })
    const npwpDoc = lodashFind(ktpNpwpDocs, { document_type: 'NPWP' })

    const column1 = [
      {
        id: 'ktp_1',
        name: <strong> Name </strong>,
        value: data.name
      },
      {
        id: 'ktp_2',
        name: <strong>Mitra Code</strong>,
        value: data.agent_code
      },
      {
        id: 'ktp_3',
        name: <strong>KTP Number</strong>,
        value: data.ktp_no
      },
      {
        id: 'ktp_4',
        name: <strong>KTP Status</strong>,
        value: lodashGet(ktpDoc, 'status', '')
      },
      {
        id: 'ktp_5',
        name: <strong>KTP Image</strong>,
        value: (
          <div>
            <div className='table-img-box'>
              <img className='table-img' src={lodashGet(ktpDoc, 'url', '')} alt='KTP' />
            </div>
            {ktpDoc && this.getImgAndReasonTemplate(ktpDoc)}
          </div>
        )
      }
    ]
    const column2 = [
      {
        id: 'npwp_1',
        name: <strong>Email Status</strong>,
        value: data.is_email_verified ? 'Verified' : 'Not Verified'
      },
      {
        id: 'npwp_2',
        name: <strong>Registered Date</strong>,
        value: moment(data.created_at).format('LL')
      },
      {
        id: 'npwp_3',
        name: <strong>NPWP Number</strong>,
        value: data.npwp_no
      },
      {
        id: 'npwp_4',
        name: <strong>NPWP Status</strong>,
        value: lodashGet(npwpDoc, 'status', '')
      },
      {
        id: 'npwp_5',
        name: <strong>NPWP Image</strong>,
        value: (
          <div>
            <div className='table-img-box'>
              <img className='table-img' src={lodashGet(npwpDoc, 'url', '')} alt='NPWP' />
            </div>
            {npwpDoc && this.getImgAndReasonTemplate(npwpDoc)}
          </div>
        )
      }
    ]
    return (
      <KTPNPWPStyle>
        <Row type='flex' align='space-between'>
          <div className='width-50'>
            {this.renderTables(column1)}
          </div>
          <div className='width-50'>
            {this.renderTables(column2)}
          </div>
        </Row>
        {this.renderAgentType()}
        {
          data.agent_ref && <Questionnaire agentRef={data.agent_ref} />
        }
        <hr />
        {
          this.getFooterNode()
        }
      </KTPNPWPStyle>
    )
  }

  renderAgentType = () => {
    const { data } = this.props
    return (
      <PermissionCheckerV2 requiredPermission='ops.view_agent_type_tax_change_btn'>
        <Row type='flex'>
          <Col xl={4} md={5} className='verify-agent-name'>Agent Type:</Col>
          <Col>
            <AgentOrgType data={data} />
          </Col>
        </Row>
      </PermissionCheckerV2>
    )
  }

  render () {
    const { data, scenario, agentOrgTypeLoading } = this.props
    const { document: ktpNpwpDocs = [] } = data

    const isZohoCase = scenario === 'zoho'
    return (
      <CircularLoader isSpining={agentOrgTypeLoading}>
        {
          isZohoCase
            ? this.renderZohoData()
            : (
              <KTPNPWPStyle>
                <PreventCopy>
                  {
                    VERIFY_MODAL_DATA.map(item => (
                      this.getKeyValueTemplate(item.name, data[item.key])
                    ))
                  }
                  {this.renderAgentType()}
                  {
                    ktpNpwpDocs.map(item => (
                      this.getImgAndReasonTemplate(item)
                    ))
                  }
                </PreventCopy>
                {
                  data.agent_ref && <Questionnaire agentRef={data.agent_ref} />
                }
                <hr />
                {
                  this.getFooterNode()
                }
              </KTPNPWPStyle>
              )
        }
      </CircularLoader>
    )
  }
}

const wrapperKTPandNPWPModal = Form.create()(KTPandNPWPModal)

export default connect(
  state => ({
    submitError: state.Error.SUBMIT_AGENT_VERIFICATION,
    agentOrgTypeLoading: state.Loading.UPDATE_AGENT_ORG_TYPE,
    submitLoading: state.Loading.SUBMIT_AGENT_VERIFICATION
  }),
  {
    submitAgentVerification
  }
)(wrapperKTPandNPWPModal)
